<script setup lang="ts">
import {onMounted,ref} from 'vue'
import UiButton from '@/components/ui/UiButton.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import {transferResultApi,type TransferBackupStatus} from '@/features/sync/modelTransfer'
import {useModelsStore} from '@/features/models/store'
import {useAppStore} from '@/stores/app'
import {errorText} from '@/features/models/api'
const rows=ref<TransferBackupStatus[]>([]),selected=ref<TransferBackupStatus|null>(null),groups=ref<string[]>([]),baseline=ref(''),busy=ref(false),error=ref(''),message=ref('')
const labels:Record<string,string>={channels:'渠道与模型',templates:'模型模版',preferences:'桌面偏好',extensions:'扩展设置',webdav:'导入的连接',accounts:'账户信息',mcp:'MCP定义'}
const label=(value:string)=>value.startsWith('skill:')?'Skill · '+value.slice(6):labels[value]??value
async function load(){busy.value=true;error.value='';try{rows.value=await transferResultApi.backups()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function choose(row:TransferBackupStatus){selected.value=row;groups.value=[...row.groups];baseline.value='';error.value='';message.value='';await preview()}
async function preview(){if(!selected.value||busy.value||!groups.value.length)return;const id=selected.value.id,scope=[...groups.value];busy.value=true;baseline.value='';error.value='';try{const value=await transferResultApi.previewRestore(id,scope);if(selected.value?.id===id&&JSON.stringify(groups.value)===JSON.stringify(scope))baseline.value=value}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function restore(){if(!selected.value||!baseline.value||busy.value)return;const models=useModelsStore();if(models.channelDirty||models.pendingRows.length||models.dirty){error.value='请先保存或还原当前编辑，再恢复所选备份；当前输入已保留。';return}busy.value=true;error.value='';try{const saved=await transferResultApi.restore(selected.value.id,[...groups.value],baseline.value);models.acceptTransfer(saved);await useAppStore().loadPreferences();selected.value=null;message.value='所选范围已恢复。'}catch(e){error.value=errorText(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="transfer-backups"><div class="transfer-backup-head"><div><h3>同步与导入前备份</h3><p>恢复所选资源在本次更新前的内容；后续相同字段如有修改，需先核对。</p></div><UiButton variant="ghost" size="sm" :disabled="busy" @click="load">刷新记录</UiButton></div><p v-if="error&&!selected" class="model-error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><p v-if="!rows.length&&!busy&&!error" class="model-muted">尚无更新前范围备份。</p><ul><li v-for="row in rows" :key="row.id"><span>{{ row.groups.map(label).join('、') }}</span><UiButton size="sm" :disabled="busy||!row.ready" @click="choose(row)">恢复所选范围</UiButton></li></ul><UiDialog :open="!!selected" title="恢复更新前备份" :busy="busy" @close="selected=null"><p>选择要恢复的范围，确认后更新已保存内容。</p><div v-if="selected" class="transfer-restore-scope"><label v-for="group in selected.groups" :key="group"><input v-model="groups" type="checkbox" :value="group" :disabled="busy" @change="baseline='';preview()" />{{ label(group) }}</label></div><p v-if="error" class="model-error" role="alert">{{ error }}</p><p v-if="!groups.length" class="model-muted">请选择至少一个范围。</p><template #actions><UiButton :disabled="busy" @click="selected=null">取消</UiButton><UiButton v-if="error" :disabled="busy||!groups.length" @click="preview">重新核对</UiButton><UiButton variant="primary" :disabled="busy||!baseline||!groups.length" :loading="busy" @click="restore">确认恢复</UiButton></template></UiDialog></section></template>
<style scoped>.transfer-backups{margin-top:24px;border-top:1px solid var(--border);padding-top:20px}.transfer-backup-head,.transfer-backups li{display:flex;justify-content:space-between;align-items:center;gap:16px}.transfer-backups ul{list-style:none;padding:0}.transfer-backups li{padding:12px 0;border-bottom:1px solid var(--border)}.transfer-backups p{color:var(--muted);font-size:var(--text-caption);line-height:1.6}.transfer-restore-scope{display:grid;gap:10px;margin:16px 0}.transfer-restore-scope label{display:flex;align-items:center;gap:8px}.transfer-backups .model-error{color:var(--red)}</style>
